import math

# 函数用于计算小于等于n的质数个数
def count_primes(n):
    sieve = [True] * (n+1)
    for x in range(2, int(n**0.5) + 1):
        if sieve[x]:
            for u in range(x*x, n+1, x):
                sieve[u] = False
    return sum(sieve) - 2  # 减去2，因为0和1不是质数

