import math

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_div = math.floor(math.sqrt(n))
    for i in range(3, 1 + max_div, 2):
        if n % i == 0:
            return False
    return True


def find_prime():
    i = 1
    while True:
        square = i*i
        next_square = (i+1)*(i+1)
        if next_square - square == 11:
            prime_candidate = square + 4
            if is_prime(prime_candidate):
                return prime_candidate
        i += 1

print(find_prime())

