        return 10 * np.cos(20 * np.pi * t - np.pi / 4)

    def x2(t):
        return -5 * np.cos(50 * np.pi * t)

    # 结合函数
    def x(t):
        return x1(t) + x2(t)

    # 找出给定函数中的最大频率
    max_freq = max(20 * np.pi, 50 * np.pi) / (2 * np.pi)

    # 根据Nyquist-Shannon采样定理，最小采样率是最大频率的两倍
    min_sampling_rate = 2 * max_freq

    return min_sampling_rate
