设$\mathbf{a}$表示$\overrightarrow{A}$，以此类推。

由于$\overline{BE}$是角平分线，根据角平分线定理可知，
\[\frac{BD}{CD} = \frac{AB}{AC} = \frac{7}{5}，\]
所以$\mathbf{d} = \frac{5}{12} \mathbf{b} + \frac{7}{12} \mathbf{c}。$

同样地，
\[\frac{AE}{CE} = \frac{AB}{BC} = \frac{7}{3}，\]
所以$\mathbf{e} = \frac{3}{10} \mathbf{a} + \frac{7}{10} \mathbf{c}。$

[asy]
unitsize(1 cm);

pair A, B, C, D, E, P;

B = (0,0);
C = (3,0);
A = intersectionpoint(arc(B,7,0,180),arc(C,5,0,180));
D = extension(A,incenter(A,B,C),B,C);
E = extension(B,incenter(A,B,C),A,C);
P = incenter(A,B,C);

draw(A--B--C--cycle);
draw(A--D);
draw(B--E);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, S);
label("$E$", E, SE);
label("$P$", P, NW);
[/asy]

分别在两个方程中解出$\mathbf{c}$，我们得到
\[\mathbf{c} = \frac{12 \mathbf{d} - 5 \mathbf{b}}{7} = \frac{10 \mathbf{e} - 3 \mathbf{a}}{7}。\]
则$12 \mathbf{d} - 5 \mathbf{b} = 10 \mathbf{e} - 3 \mathbf{a}$，所以$3 \mathbf{a} + 12 \mathbf{d} = 5 \mathbf{b} + 10 \mathbf{e}$，或者
\[\frac{3}{15} \mathbf{a} + \frac{12}{15} \mathbf{d} = \frac{5}{15} \mathbf{b} + \frac{10}{15} \mathbf{e}。\]
由于两边向量的系数总和为1，这一左边向量位于直线$AD$上，而右边向量位于直线$BE$上。因此，这个共有的向量是$\mathbf{p}$。此外，$\frac{BP}{PE} = \frac{10}{5} = 2$。因此，答案是2。

下面是使用线性三角形元素求解给定问题的MATLAB程序：
```MATLAB
function poisson_fem
    % 定义网格大小
    n = 20;
    [p, t] = create_mesh(n);

    % 组装刚度矩阵和载荷向量
    [K, F] = assemble(p, t);

    % 应用边界条件
    [K, F] = apply_boundary_conditions(K, F, p);

    % 解线性系统
    u = K \ F;

    % 绘制解
    plot_solution(p, t, u);
end

function [p, t] = create_mesh(n)
    [p, t] = square_mesh(n);
end

function [K, F] = assemble(p, t)
    N = size(p, 1);
    K = sparse(N, N);
    F = zeros(N, 1);

    for i = 1:size(t, 1)
        nodes = t(i, 1:3);
        vertices = p(nodes, :);
        [Ke, Fe] = element_stiffness_matrix(vertices);
        K(nodes, nodes) = K(nodes, nodes) + Ke;
        F(nodes) = F(nodes) + Fe;
    end
end

function [Ke, Fe] = element_stiffness_matrix(vertices)
    area = polyarea(vertices(:, 1), vertices(:, 2));
    B = [vertices(2, 2) - vertices(3, 2), vertices(3, 2) - vertices(1, 2), vertices(1, 2) - vertices(2, 2);
         vertices(3, 1) - vertices(2, 1), vertices(1, 1) - vertices(3, 1), vertices(2, 1) - vertices(1, 1)];
    C = B' * B;
    Ke = (1 / (4 * area)) * C;

    f = @(x, y) 2 * (x^2 - x) * (y^2 - y);
    Fe = (area / 3) * arrayfun(f, vertices(:, 1), vertices(:, 2));
end

function [K, F] = apply_boundary_conditions(K, F, p)
    boundary_nodes = find(p(:, 1) == 0 | p(:, 1) == 1 | p(:, 2) == 0 | p(:, 2) == 1);
    K(boundary_nodes, :) = 0;
    K(:, boundary_nodes) = 0;
