def count_two_digit_factors(n):
    factor_pairs = []
    for i in range(10, 100):
        if n % i == 0:
            factor = n // i
            if factor in range(10, 100):
                pair = sorted([i, factor])
                if pair not in factor_pairs:
                    factor_pairs.append(pair)
    return len(factor_pairs)

