def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


def prime_generator():
    yield 2
    i = 3
    while True:
        if is_prime(i):
            yield i
        i += 2


def prime_sum():
    total = 0
    prime_gen = prime_generator()
    while True:
        prime = next(prime_gen)
        total += prime
        yield total


def first_n_prime_sums(n):
    prime_sum_gen = prime_sum()
    return [next(prime_sum_gen) for _ in range(n)]


def count_prime_sums(n):
    prime_sums = first_n_prime_sums(n)
    return sum(is_prime(p_sum) for p_sum in prime_sums)

