def num_routes(n, m):
    # 创建一个二维数组来存储路径数量
    routes = [[0 for _ in range(m+1)] for _ in range(n+1)]

    # 到达第一行或第一列的任何单元格只有一条路径
    for i in range(n+1):
        routes[i][0] = 1
    for j in range(m+1):
        routes[0][j] = 1

    # 对于其他单元格，到达该单元格的路径数量是到达其上方单元格和左侧单元格路径数量之和
    for i in range(1, n+1):
        for j in range(1, m+1):
            routes[i][j] = routes[i-1][j] + routes[i][j-1]

    return routes[n][m]

