def solve():
    import math

    # 定义函数及其导数
    def f(x):
        return x - math.exp(-x)

    def df(x):
        return 1 + math.exp(-x)

    # 寻找初始近似值
    a = 0
    b = 1
    while f(a) * f(b) > 0:
        a += 1
        b += 1

    # 实现假位法（Regula-Falsi方法）
    def regula_falsi(a, b, tol=1e-3, max_iter=1000):
        c = a
        for i in range(max_iter):
            c = b - f(b) * (b - a) / (f(b) - f(a))
            if abs(c - b) < tol:
                break
            a, b = b, c
        return c

    # 找到根
    root = regula_falsi(a, b)

    return round(root, 3)
print(solve())

